adhyātmaṁ karma cākhilam\"}}]}]]]}]\n"])self.__next_f.push([1,"2c:[\"$\",\"div\",\"2333-synonyms,2333-synonyms\",{\"className\":\"av-synonyms\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Synonyms\"}],[[\"$\",\"$L29\",\"child-2336\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:2:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-justify\",\"children\":[[\"$\",\"span\",\"wfwundefined-0\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-jarā\",{\"href\":\"/en/search/synonyms/?original=jarā\",\"children\":[\"$\",\"em\",null,{\"children\":\"jarā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"from old age\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-1\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-maraṇa\",{\"href\":\"/en/search/synonyms/?original=maraṇa\",\"children\":[\"$\",\"em\",null,{\"children\":\"maraṇa\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"and death\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-2\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mokṣāya\",{\"href\":\"/en/search/synonyms/?original=mokṣāya\",\"children\":[\"$\",\"em\",null,{\"children\":\"mokṣāya\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"for the purpose of liberation\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-3\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-mām\",{\"href\":\"/en/search/synonyms/?original=mām\",\"children\":[\"$\",\"em\",null,{\"children\":\"mām\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"Me\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-4\",{\"className\":\"inline\